<?php
$uid = (int)$u['id']; $ref = preg_replace('/[^A-Z0-9]/', '', (string)($_GET['ref'] ?? ''));
$t = row('SELECT t.*, fu.name AS from_name, fu.id AS from_uid, tu.name AS to_name, tu.id AS to_uid FROM transactions t LEFT JOIN wallets fw ON fw.id=t.from_wallet_id LEFT JOIN users fu ON fu.id=fw.user_id LEFT JOIN wallets tw ON tw.id=t.to_wallet_id LEFT JOIN users tu ON tu.id=tw.user_id WHERE t.ref=?', [$ref]);
$acc = Activity::accountIds($uid); $mine = $t && ((int)$t['from_uid'] === $uid || (int)$t['to_uid'] === $uid || val('SELECT 1 FROM ledger_entries WHERE txn_id=? AND account_id IN (' . implode(',', $acc) . ')', [$t['id']]));
if (!$t || (!$mine && $u['role'] !== 'admin')) { http_response_code(404); echo page_head('Receipt') . card('', empty_state('Receipt not found.')); return; }
handle('cancel_hold', function () use ($uid, $t) { Pay::cancelHold($uid, (int)$t['id']); return 'Transfer cancelled and refunded in full.'; });
handle('open_dispute', function () use ($uid, $t) { $id = Disputes::open($uid, (int)$t['id'], null, (string)$_POST['reason']); flash('ok', 'Dispute opened. An administrator will review it.'); redirect(url('disputes', ['id' => $id])); });
$entries = rows('SELECT e.*, a.name FROM ledger_entries e JOIN ledger_accounts a ON a.id=e.account_id WHERE e.txn_id=? ORDER BY e.id', [$t['id']]); $hold = row('SELECT * FROM transfer_holds WHERE txn_id=?', [$t['id']]);
$tl = rows("SELECT * FROM timeline_events WHERE entity_type='transfer' AND entity_id=? ORDER BY id", [$t['id']]); $dsp = row('SELECT * FROM disputes WHERE txn_id=? ORDER BY id DESC LIMIT 1', [$t['id']]);
echo page_head('Receipt', $t['ref'], '<a class="btn secondary sm" href="' . e(url('export', ['kind' => 'receipt', 'ref' => $ref])) . '">' . e(t('Download')) . ' PDF</a> <button class="btn secondary sm no-print" onclick="window.print()" type="button">Print</button>');
$kv = '<dl class="kv"><dt>Status</dt><dd>' . badge($t['status']) . '</dd><dt>Type</dt><dd>' . e(type_label($t['type'])) . '</dd><dt>Date</dt><dd>' . e(fdate($t['created_at'])) . '</dd><dt>From</dt><dd>' . e($t['from_name'] ?? '-') . '</dd><dt>To</dt><dd>' . e($t['to_name'] ?? '-') . '</dd><dt>Amount</dt><dd>' . mny($t['amount'], $t['currency']) . '</dd><dt>Fee</dt><dd>' . mny($t['fee'], $t['currency']) . '</dd><dt>Category</dt><dd>' . e($t['category']) . '</dd><dt>Note</dt><dd style="font-weight:400">' . e($t['note']) . '</dd></dl>';
if ($hold && $hold['status'] === 'held' && (int)$t['from_uid'] === $uid) $kv .= '<div class="alert warn" style="margin-top:12px;display:block"><div>Time left to cancel: <span class="countdown" data-countdown="' . strtotime($hold['release_at']) . '" data-done-text="Released">--:--</span></div>' . form_start('cancel_hold') . btn('Cancel transfer', 'danger sm') . '</form></div>';
$rows = []; foreach ($entries as $e) $rows[] = [e($e['phase']), e($e['name']), $e['direction'] === 'D' ? e($e['amount']) : '', $e['direction'] === 'C' ? e($e['amount']) : ''];
$led = tbl(['Phase', 'Account', ['Debit', 'num'], ['Credit', 'num']], $rows) . '<p class="hint">Double-entry: for each phase, total debits equal total credits. Wallet accounts hold your balance; system accounts hold fees, held transfers and escrow.</p>';
$side = ''; if ($tl) { $side .= '<ul class="timeline">'; foreach ($tl as $x) $side .= '<li><strong>' . e(ucfirst($x['event'])) . '</strong> <span class="hint">' . e(fdate($x['created_at'])) . '</span><div class="hint">' . e($x['note']) . '</div></li>'; $side .= '</ul>'; }
if ($dsp) $side .= '<p>Dispute <a href="' . e(url('disputes', ['id' => $dsp['id']])) . '">' . e($dsp['ref']) . '</a> ' . badge($dsp['status']) . '</p>';
elseif (in_array($t['status'], ['completed'], true) && $mine && !in_array($t['type'], ['topup', 'conversion', 'pocket_deposit', 'pocket_withdraw'], true)) $side .= form_start('open_dispute') . '<div class="field"><label for="reason">Something wrong with this payment?</label><textarea id="reason" name="reason" rows="3" required minlength="5" maxlength="255" placeholder="Describe the problem"></textarea></div>' . btn('Open dispute', 'secondary sm') . '</form>';
echo '<div class="grid g2">' . card('Details', $kv) . card('Status timeline and support', $side ?: '<p class="muted">No events yet.</p>') . '</div><div style="height:16px"></div>' . card('Ledger entries (traceable balance effect)', $led);
